import pathlib,json,ipaddress,tempfile,os,stat
def migrate(active,candidate,plan,probe,report):
    active,candidate,plan,report=map(lambda x:pathlib.Path(x).resolve(),(active,candidate,plan,report))
    base=pathlib.Path.cwd().resolve()
    if any(not p.is_relative_to(base) for p in [active,candidate,plan,report]) or len({active,candidate,plan,report})!=4:raise ValueError('four distinct workspace paths required')
    def config(path):
        obj=json.loads(path.read_text())
        if set(obj)!={'server','port','search','ndots'} or not isinstance(obj['server'],str) or not ipaddress.ip_address(obj['server']).is_loopback or ipaddress.ip_address(obj['server']).version!=4:raise ValueError('loopback resolver config required')
        if type(obj['port']) is not int or not 1<=obj['port']<=65535 or type(obj['ndots']) is not int or not 0<=obj['ndots']<=5:raise ValueError('port/ndots invalid')
        if not isinstance(obj['search'],list) or len(obj['search'])>4 or any(not isinstance(s,str) or not s or any(c not in 'abcdefghijklmnopqrstuvwxyz0123456789.-' for c in s) for s in obj['search']):raise ValueError('bounded search suffixes required')
        return obj
    def atomic(path,data,mode):
        fd,temp=tempfile.mkstemp(prefix='.resolver-',dir=path.parent)
        try:
            with os.fdopen(fd,'wb') as f:f.write(data);f.flush();os.fsync(f.fileno())
            os.chmod(temp,mode);os.replace(temp,path)
        finally:
            if os.path.exists(temp):os.unlink(temp)
    outcome={'status':'rejected','checks':[],'error':None,'rollback_verified':False};changed=False
    before=active.read_bytes();mode=stat.S_IMODE(active.stat().st_mode)
    def verify(configuration,cases,stage):
        for case in cases:
            observed=probe(configuration,case)
            item={'stage':stage,'name':case['name'],'rcode':observed['rcode'],'answers':observed['answers'],'queries':observed['queries'],'transports':observed['transports']}
            good=observed['rcode']==case['rcode'] and sorted(observed['answers'])==sorted(case['answers'])
            if observed['rcode'] not in {'NOERROR','NXDOMAIN'}:good=False
            if case.get('require_tcp') and 'tcp' not in observed['transports']:good=False
            item['passed']=good;outcome['checks'].append(item)
            if not good:raise RuntimeError('resolver acceptance failed')
    try:
        previous=config(active);replacement=config(candidate);cases=json.loads(plan.read_text())
        if not isinstance(cases,list) or not cases or len(cases)>12:raise ValueError('bounded nonempty plan required')
        if len({c['name'] for c in cases})!=len(cases):raise ValueError('duplicate plan names')
        for case in cases:
            if not isinstance(case.get('name'),str) or not case['name'] or case.get('rcode') not in {'NOERROR','NXDOMAIN'} or not isinstance(case.get('answers'),list):raise ValueError('invalid expected case')
            if any(not isinstance(a,str) or ipaddress.ip_address(a).version!=4 for a in case['answers']):raise ValueError('expected IPv4 values required')
            if case['rcode']=='NXDOMAIN' and case['answers']:raise ValueError('negative case cannot have answers')
            if 'require_tcp' in case and type(case['require_tcp']) is not bool:raise ValueError('require_tcp must be bool')
        verify(previous,cases,'baseline');verify(replacement,cases,'candidate')
        changed=True;atomic(active,json.dumps(replacement,indent=2).encode(),mode)
        verify(config(active),cases,'after_switch');outcome['status']='committed'
    except Exception as error:
        outcome['error']=type(error).__name__
        if changed:
            try:
                atomic(active,before,mode);verify(previous,cases,'rollback')
                outcome['rollback_verified']=True;outcome['status']='rolled_back'
            except Exception as recovery:
                outcome['status']='rollback_failed';outcome['rollback_error']=type(recovery).__name__
    atomic(report,json.dumps(outcome,indent=2).encode(),0o600)
    return outcome
```

probe是实训框架提供的真实DNS协议工具，不是布尔模拟。迁移程序负责完整计划、切换门禁、实际复测、恢复文件与服务状态两者的区分。NOERROR空回答与NXDOMAIN不能混为一谈，SERVFAIL不属于可接受的预期否定应答。

原理补充：
交付查询域分类、条件转发、DNSSEC策略和客户端配置来源。分别验证公网、内部区、反向区与不存在名称，检查缓存、超时和上游不可达行为，避免新解析器把内部查询泄露到公网。客户端可能经系统服务、本地缓存或应用自带解析，需确认实际路径。验收多标签名、绝对域名、UDP/TCP及大响应，比较答案与延迟。发现内部视图不一致时停止推广并恢复原解析配置，保留旧服务覆盖缓存窗口；清空所有终端缓存不是必需且可能制造上游查询尖峰。

